  const items = sale?.items || [];
  const isA5 = !!p.printA5;
  const fontScale = Math.min(2, Math.max(0.5, Number(p.fontSize ?? 100) / 100));
  const logo = company?.logo ? `<img class="company-logo" src="${String(company.logo).replace(/"/g, "&quot;")}" alt="Company logo">` : ``;
  const addrLines = invoiceAddressLines(company);
  const companyName = String(company?.name || "").trim().toUpperCase();
  const companyPhone = String(company?.phoneNumber || "").trim();
  const companyEmail = String(company?.email || "").trim();
  const dueDate = sale?.dueDate || sale?.date;
  const isQuotation = String(sale?.documentType || "").toLowerCase() === "quotation";
  const documentTitle = isQuotation ? "QUOTATION" : p.invoiceTitle || "INVOICE";
  const documentNoLabel = isQuotation ? "Quotation No." : "Invoice No.";
  const documentDueLabel = isQuotation ? "Valid until:" : "Due date:";
  const paid = Number(sale?.paymentAmount || 0);
  const total = Number(sale?.total || 0);
  const due = Math.max(0, total - paid);
  const showTax = p.taxColumn !== false;
  const showDiscount = p.discountColumn !== false;
  const hasPayments = Array.isArray(sale?.payments) && sale.payments.length > 0;
  const showPaymentTypes = isQuotation ? hasPayments : p.paymentTypes !== false;
  const showOutstanding = isQuotation ? hasPayments : p.outstandingBalance !== false;
  const rawPayments = hasPayments ? sale.payments : !isQuotation && paid > 0 ? [{ payment: sale?.payment || "Cash", amount: paid, source: "payment" }] : [];
  const paymentLines = rawPayments.map((x) => {
    const method = String(x.payment || "Payment");
    const source = String(x.source || "").toLowerCase();
    const label = isQuotation ? method : source === "deposit" ? `Deposit (${method})` : `Payment (${method})`;
    return `<div><span>${escapeHtml(label)}</span><b>${escapeHtml(money(x.amount))}</b></div>`;
  }).join("");
  const paymentHeading = isQuotation ? "Deposit received:" : "Payment breakdown:";
  const paidLabel = isQuotation ? "Deposit received:" : "Paid amount:";
  const dueLabel = isQuotation ? "Balance due:" : "Amount due:";
  const itemRows = items.map((i, n) => {
    const warranty = Boolean(i.warrantyText) || Boolean(i.warrantyEnabled) && Number(i.warrantyYears || 0) > 0;
    const maintenance = Boolean(i.maintenanceText) || Boolean(i.maintenanceEnabled) && Number(i.maintenanceCount || 0) > 0;
    const description = String(i.description || "").trim();
    const descriptionHtml = description ? `<div class="invoice-item-service invoice-item-description">${escapeHtml(description).replace(/\n/g, "<br>")}</div>` : "";
    const serviceLines = `${descriptionHtml}${warranty ? `<div class="invoice-item-service">${escapeHtml(i.warrantyText || `Warranty ${Math.max(1, Number(i.warrantyYears) || 1)} Year`)}</div>` : ""}${maintenance ? `<div class="invoice-item-service">${escapeHtml(i.maintenanceText || `Free Maintenance ${Math.max(1, Number(i.maintenanceCount) || 1)} x`)}</div>` : ""}`;
    return `<tr><td class="col-no">${n + 1}</td><td class="col-item"><div>${escapeHtml(i.name || "")}</div>${serviceLines}</td><td class="col-qty num">${escapeHtml(i.qty || 0)}</td><td class="col-unit num">${escapeHtml(Number(i.price || 0).toFixed(2))}</td>${showTax ? `<td class="col-tax num">${escapeHtml(money(i.tax || 0))}</td>` : ""}${showDiscount ? `<td class="col-discount num">${escapeHtml(money(i.discount || 0))}</td>` : ""}<td class="col-total num">${escapeHtml(money(i.lineTotal ?? i.total ?? Number(i.price || 0) * Number(i.qty || 0) - Number(i.discount || 0) + Number(i.tax || 0)))}</td></tr>`;
  }).join("");
  const columns = 5 + (showTax ? 1 : 0) + (showDiscount ? 1 : 0);
  const publicNote = String(sale?.note || "").trim();
  const customerAddress = customerAddressText(customer);
  const customerLines = [
    customerAddress ? `<div class="billto-detail"><b>Address:</b> ${escapeHtml(customerAddress)}</div>` : "",
    customer?.phone && customer.phone !== "-" ? `<div class="billto-detail"><b>Phone:</b> ${escapeHtml(customer.phone)}</div>` : "",
    customer?.email && customer.email !== "-" ? `<div class="billto-detail"><b>Email:</b> ${escapeHtml(customer.email)}</div>` : "",
    customer?.vehicleNumber && customer.vehicleNumber !== "-" ? `<div class="billto-detail"><b>Vehicle No.:</b> ${escapeHtml(customer.vehicleNumber)}</div>` : "",
    p.customerTaxNumber && customer?.taxNumber ? `<div class="billto-detail"><b>Tax No.:</b> ${escapeHtml(customer.taxNumber)}</div>` : "",
    p.customerCode && customer?.code ? `<div class="billto-detail"><b>Code:</b> ${escapeHtml(customer.code)}</div>` : ""
  ].filter(Boolean).join("");
  const footerText = String(p.footer || "").trim();
  return `<div class="invoice-page ${isA5 ? "invoice-a5" : "invoice-a4"}" style="--invoice-font-scale:${fontScale}">
  <div class="invoice-head"><div class="invoice-company-info"><div class="invoice-title">${escapeHtml(documentTitle)}</div>${companyName ? `<div class="company-name">${escapeHtml(companyName)}</div>` : ""}${addrLines.length ? `<div class="company-address">${addrLines.map((line) => `<div>${escapeHtml(line)}</div>`).join("")}</div>` : ""}${companyPhone ? `<div class="company-contact">Phone: <span>${escapeHtml(companyPhone)}</span></div>` : ""}${companyEmail ? `<div class="company-contact">Email: <span>${escapeHtml(companyEmail)}</span></div>` : ""}</div><div class="invoice-company"><div class="invoice-company-top">${logo}</div></div></div>
  <div class="invoice-header-line"></div>
  <div class="invoice-info-grid"><div class="billto-block"><b>Bill to</b><div class="billto-name">${escapeHtml(customer?.name || sale?.customerName || "Walk-in customer")}</div>${customerLines}</div><div class="invoice-meta"><div><b>${documentNoLabel}</b> ${escapeHtml(sale?.no || "")}</div><div><b>Date:</b> ${escapeHtml(formatInvoiceDate(sale?.date))}</div><div><b>${documentDueLabel}</b> ${escapeHtml(formatInvoiceDate(dueDate))}</div>${isQuotation ? `<div><b>Status:</b> ${escapeHtml(sale?.status || "Draft")}</div>` : `<div><b>Payment status:</b> ${escapeHtml(sale?.paymentStatus || (sale?.paid === false || due > 0 ? "Unpaid" : "Paid"))}</div>`}</div></div>
  <table class="invoice-table"><thead><tr><th class="col-no">#</th><th class="col-item">Item</th><th class="col-qty">Quantity</th><th class="col-unit">Unit price</th>${showTax ? `<th class="col-tax">Tax</th>` : ""}${showDiscount ? `<th class="col-discount">Discount</th>` : ""}<th class="col-total">Total</th></tr></thead><tbody>${itemRows || `<tr><td colspan="${columns}">No items</td></tr>`}</tbody></table>
  <div class="invoice-bottom-row"><div class="invoice-total"><span>Total</span><b>${escapeHtml(money(total))}</b></div>${showPaymentTypes || showOutstanding ? `<div class="payment-summary">${showPaymentTypes ? `<div class="payment-heading"><b>${paymentHeading}</b></div>${paymentLines}` : ""}${showOutstanding ? `<div><span>${paidLabel}</span><b>${escapeHtml(money(paid))}</b></div><div><span>${dueLabel}</span><b>${escapeHtml(money(due))}</b></div>` : ""}</div>` : ""}</div>
  ${publicNote ? `<div class="invoice-note"><div class="invoice-note-title">Add notes</div><div class="invoice-note-text">${escapeHtml(publicNote).replace(/\n/g, "<br>")}</div></div>` : ""}
  ${footerText ? `<div class="invoice-footer">${escapeHtml(footerText).replace(/\n/g, "<br>")}</div>` : `<div class="invoice-footer">Page 1</div>`}
 </div>`;
