  const [form, setForm] = reactExports.useState(empty);
  const [tab, setTab] = reactExports.useState("General");
  const [deleteTarget, setDeleteTarget] = reactExports.useState(null);
  const rows = customers.filter((c) => {
    const q = search.toLowerCase();
    const text = [c.name, c.code, c.taxNumber, c.phone, c.email, c.city, c.country].join(" ").toLowerCase();
    const type = kind === "All" || kind === "Customers" && c.isCustomer !== false || kind === "Suppliers" && c.isSupplier;
    return type && text.includes(q);
  });
  const generateCustomerCode = () => {
    const numbers = customers.map((c) => {
      const match = String(c.code || "").match(/^SP(\d{6})$/i);
      return match ? Number(match[1]) : null;
    }).filter(Number.isFinite);
    const next = numbers.length ? Math.max(...numbers) + 1 : 0;
    return `SP${String(next).padStart(6, "0")}`;
  };
