    const isEdit = editing !== "new";
    const ok = await showActionConfirm(isEdit ? "Confirm Customer Update" : "Confirm Customer Save", isEdit ? `Update customer "${prepared.name}"?` : `Save customer "${prepared.name}"?`, isEdit ? "Yes" : "Yes");
    if (!ok) return;
    let next;
    if (editing === "new") next = [...customers, { ...prepared, id: uid(), visits: 0, spend: 0 }];
