    const head = ["Code", "Name", "Tax Number", "Street Name", "Building Number", "Additional Street Name", "Plot Identification", "District", "Postcode", "City", "State / Province", "Country", "Phone", "Email", "Vehicle Number", "Customer", "Supplier", "Active", "Discount (%)", "Due Date Period (days)", "Loyalty Card"];
    const body = rows.map((c) => [c.code || "", c.name, c.taxNumber || "", c.streetName || "", c.buildingNumber || "", c.additionalStreetName || "", c.plotIdentification || "", c.district || "", c.postalCode || "", c.city || "", c.state || "", c.country || "", c.phone || "", c.email || "", c.vehicleNumber || "", c.isCustomer !== false ? "Yes" : "No", c.isSupplier ? "Yes" : "No", c.enabled !== false ? "Yes" : "No", Number(c.discount || 0).toFixed(2), Number(c.dueDatePeriod || 0), c.loyaltyCard || ""]);
